-- The predecessor runtime must fail closed: version-1 workers do not know
-- local cancellation. The check name is generated by the fixed 0083 DDL.
ALTER TABLE order_refund_runtime DROP CHECK order_refund_runtime_chk_2;
UPDATE order_refund_runtime SET version=2;
ALTER TABLE order_refund_runtime ADD CONSTRAINT ck_order_refund_attempt_runtime CHECK(version=2);
-- Keep failed, provider-canceled and never-dispatched canceled instructions as
-- immutable history. Only an explicit new instruction may follow one of them.
ALTER TABLE order_refund_operations
 ADD COLUMN previous_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
 ADD COLUMN canceled_at DATETIME(6) NULL,
 ADD COLUMN canceled_by VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL,
 ADD INDEX refund_request_history(request_id),
 ADD UNIQUE INDEX refund_attempt_successor(previous_operation_id),
 ADD CONSTRAINT fk_refund_previous FOREIGN KEY(previous_operation_id) REFERENCES order_refund_operations(operation_id),
 ADD CONSTRAINT fk_refund_canceled_actor FOREIGN KEY(canceled_by) REFERENCES admin_users(id),
 ADD CONSTRAINT ck_refund_local_cancel CHECK((canceled_at IS NULL AND canceled_by IS NULL) OR (canceled_at IS NOT NULL AND canceled_by IS NOT NULL AND dispatched_at IS NULL AND state='pending' AND observation IS NULL AND applied=FALSE));
ALTER TABLE order_refund_operations DROP INDEX request_id;
ALTER TABLE order_refund_operations
 ADD COLUMN active_request_id VARCHAR(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin GENERATED ALWAYS AS (CASE WHEN canceled_at IS NULL AND state NOT IN ('failed','canceled') THEN request_id ELSE NULL END) STORED,
 ADD UNIQUE INDEX refund_one_active_request(active_request_id);
CREATE TABLE order_refund_cancellations (
 operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
 refund_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,
 actor_id VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 order_id VARCHAR(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
 request_id VARCHAR(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin NOT NULL,
 created_at DATETIME(6) NOT NULL,
 FOREIGN KEY(refund_operation_id) REFERENCES order_refund_operations(operation_id),
 FOREIGN KEY(actor_id) REFERENCES admin_users(id)
) ENGINE=InnoDB;
